    <script>
        const triggerQuickReply = (text) => {
            if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${text}|/trigger`);
            } else { console.log('SillyTavern environment not detected. Would send:', text); }
        };

        document.addEventListener('DOMContentLoaded', () => {
            initThemeToggle();
            const storyRenderer = new StoryRenderer('yaml-data-source');
            storyRenderer.init();
            document.getElementById('options-container').addEventListener('click', (e) => {
                const li = e.target.closest('li');
                if (li && li.parentElement.id === 'options-list') {
                    const optionText = li.textContent.trim();
                    triggerQuickReply(optionText);
                    li.style.transform = 'scale(0.98)';
                    setTimeout(() => { li.style.transform = 'scale(1)'; }, 200);
                }
            });
        });

        function initThemeToggle() {
            const themeButtons = document.querySelectorAll('.theme-btn');
            const bodyElement = document.body;
            const savedTheme = localStorage.getItem('petHomeThemeV3') || 'night';
            function switchToTheme(theme) {
                bodyElement.className = 'font-sans antialiased';
                bodyElement.classList.add(`${theme}-mode`);
                themeButtons.forEach(btn => btn.classList.toggle('active', btn.getAttribute('data-theme') === theme));
            }
            switchToTheme(savedTheme);
            themeButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const theme = button.getAttribute('data-theme');
                    switchToTheme(theme);
                    localStorage.setItem('petHomeThemeV3', theme);
                });
            });
        }

        class StoryRenderer {
            constructor(dataSourceId) {
                this.dataSourceId = dataSourceId;
                this.yamlData = null; this.rawYamlContent = ""; this.rootNode = null;
                this.iconMap = {
                    '名字': 'fa-id-card-o', '动态': 'fa-commenting-o', '着装': 'fa-shopping-bag', '行动': 'fa-paw',
                    '秘密花园': 'fa-diamond', '软软的胸脯': 'fa-heart-o', '小菊花': 'fa-circle-o', '胸部': 'fa-heart-o', '小穴': 'fa-diamond', '肛门': 'fa-circle-o',
                    '主人的🦴': 'fa-fire', '主人的🧶': 'fa-codepen', '阳具': 'fa-fire', '睾丸': 'fa-codepen',
                    'default': 'fa-info-circle'
                };
                this.initElements();
            }

            initElements() {
                this.elements = {
                    timeDisplay: document.getElementById('time-display'),
                    locationDisplay: document.getElementById('location-display'),
                    charactersContainer: document.getElementById('characters-container'),
                    actionOwner: document.getElementById('action-owner'),
                    optionsList: document.getElementById('options-list')
                };
            }

            init() {
                try {
                    this.loadYamlFromScriptTag(); this.findRootNode(); this.renderAll(); this.setupEventListeners();
                } catch (error) { this.handleError(error); }
            }

            loadYamlFromScriptTag() {
                const scriptElement = document.getElementById(this.dataSourceId);
                if (!scriptElement) throw new Error('未找到YAML数据源');
                this.rawYamlContent = scriptElement.textContent.trim();
                if (!this.rawYamlContent) throw new Error('YAML内容为空');
                this.yamlData = jsyaml.load(this.rawYamlContent);
            }

            extractEmojis(text) { return text.match(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu) || []; }
            getEmojiForField(fieldName) {
                const lines = this.rawYamlContent.split('\n');
                for (const line of lines) { if (line.includes(fieldName) && line.includes(':')) {
                        const emojis = this.extractEmojis(line.split(':')[1].trim());
                        if (emojis.length > 0) return emojis[0];
                } } return '🐾';
            }
            findRootNode() { this.rootNode = Object.keys(this.yamlData)[0]; }

            renderAll() {
                const rootData = this.yamlData[this.rootNode];
                this.renderHeaderInfo(rootData); this.renderCharacters(rootData); this.renderActionOptions(rootData);
            }

            findFieldByKeywords(data, keywords) {
                if (!data || typeof data !== 'object') return null;
                const fields = Object.keys(data);
                for (const field of fields) { for (const keyword of keywords) {
                    if (field.toLowerCase().includes(keyword.toLowerCase())) return field;
                } } return null;
            }

            renderHeaderInfo(rootData) {
                const dateTimeField = this.findFieldByKeywords(rootData, ['日期', '时间']);
                const locationField = this.findFieldByKeywords(rootData, ['地点', '位置']);
                if(dateTimeField) {
                    this.elements.timeDisplay.textContent = rootData[dateTimeField].replace(/[^\p{L}\p{N}\s:年日月点分]/gu, '');
                    this.elements.timeDisplay.parentNode.querySelector('.emoji').textContent = this.getEmojiForField(dateTimeField);
                }
                if(locationField) {
                    this.elements.locationDisplay.textContent = rootData[locationField].replace(/[^\p{L}\p{N}\s-]/gu, '');
                    this.elements.locationDisplay.parentNode.querySelector('.emoji').textContent = this.getEmojiForField(locationField);
                }
            }

            renderCharacters(rootData) {
                const listField = this.findFieldByKeywords(rootData, ['成员列表', '用户列表', 'list']);
                const userList = listField && Array.isArray(rootData[listField]) ? rootData[listField] : [];
                this.elements.charactersContainer.innerHTML = '';
                if (userList.length === 0) {
                    this.elements.charactersContainer.innerHTML = this.createEmptyState('没有家庭成员信息');
                    return;
                }
                userList.forEach(item => {
                    const itemField = this.findFieldByKeywords(item, ['成员', '用户', 'user']);
                    const card = this.createCharacterCard(itemField ? item[itemField] : item);
                    if (card) this.elements.charactersContainer.appendChild(card);
                });
            }

            createCharacterCard(userData) {
                if (!userData || typeof userData !== 'object') return null;
                const card = document.createElement('div');
                card.className = 'character-card theme-transition card-hover border-2 p-4';

                const nameField = this.findFieldByKeywords(userData, ['名字', 'name']);
                let userName = nameField ? userData[nameField] : '未知成员';
                const nameEmojis = this.extractEmojis(userName);
                const cleanName = userName.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();

                let cardHTML = `<h3 class="font-extrabold text-xl mb-3 pb-3 border-b-2 border-main/50 border-dashed theme-transition flex items-center">
                                    ${nameEmojis.length > 0 ? nameEmojis[0] + ' ' : ''}${cleanName}
                                </h3><ul class="space-y-2.5 text-sm">`;

                Object.keys(userData).forEach(key => {
                    if (key === nameField) return;
                    const value = userData[key];
                    const iconClass = this.iconMap[key] || this.iconMap.default;
                    let valueText = (typeof value === 'object' && value !== null) ? '(见详情)' : String(value);
                    const cleanValueText = valueText.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();

                    cardHTML += `<li class="flex items-start text-subtle">
                                    <i class="fa ${iconClass} text-main w-5 text-center mr-2.5 mt-0.5"></i>
                                    <div class="flex-1"><strong class="font-bold text-main">${key}:</strong> ${cleanValueText}</div>
                                 </li>`;
                });
                cardHTML += `</ul>`;
                card.innerHTML = cardHTML;
                return card;
            }

            renderActionOptions(rootData) {
                const actionOptionsField = this.findFieldByKeywords(rootData, ['行动选项', '选项']);
                const actionOptions = actionOptionsField ? rootData[actionOptionsField] : {};
                const ownerField = this.findFieldByKeywords(actionOptions, ['名字', 'name']);
                let ownerName = ownerField ? actionOptions[ownerField] : '主人';
                const ownerEmojis = this.extractEmojis(ownerName);
                const cleanOwnerName = ownerName.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();
                this.elements.actionOwner.innerHTML = `${ownerEmojis.length > 0 ? ownerEmojis[0] + ' ' : ''}${cleanOwnerName}`;

                const optionsField = this.findFieldByKeywords(actionOptions, ['选项', 'choice']);
                const options = optionsField && Array.isArray(actionOptions[optionsField]) ? actionOptions[optionsField] : [];
                this.elements.optionsList.innerHTML = '';
                if (options.length === 0) {
                    this.elements.optionsList.innerHTML = this.createEmptyState('没有可用指令'); return;
                }
                options.forEach(optionText => {
                    const cleanOptionText = optionText.replace(/^\d+\.\s*/, '').replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();
                    const optionItem = document.createElement('li');
                    optionItem.className = 'px-3 py-2 border-l-4 theme-transition text-subtle';
                    optionItem.innerHTML = cleanOptionText;
                    this.elements.optionsList.appendChild(optionItem);
                });
            }

            createEmptyState(message) { return `<div class="text-center py-4 text-subtle theme-transition"><i class="fa fa-info-circle mr-1"></i>${message}</div>`; }

            setupEventListeners() {
                const detailsElement = document.querySelector('details');
                const contentElement = this.elements.charactersContainer;
                // Set initial max-height for smooth opening
                if (detailsElement.open) {
                    contentElement.style.maxHeight = contentElement.scrollHeight + 'px';
                } else {
                    contentElement.style.maxHeight = '0px';
                }

                detailsElement.addEventListener('toggle', () => {
                    if (detailsElement.open) {
                        contentElement.style.maxHeight = contentElement.scrollHeight + 'px';
                    } else {
                        contentElement.style.maxHeight = '0px';
                    }
                });
            }

            handleError(error) {
                console.error('渲染错误:', error);
                this.elements.charactersContainer.innerHTML = `<div class="bg-red-500/10 border border-red-500/30 text-red-400 px-4 py-3 rounded-lg" role="alert"><strong>加载失败:</strong> ${error.message}</div>`;
            }
        }
    </script>
</body>
</html>
