            const paragraphs = text
                .replace(/\n\s*\n/g, '\n\n')
                .split(/\n\s*\n/)
                .filter(paragraph => paragraph.trim().length > 0);

            // 6. 包装成段落元素
            const formattedParagraphs = paragraphs.map(paragraph => {
